using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.Xml;using MP1SkinStudio;using MP1SkinStudio.Live;
class StudioProbe{
 static StudioForm form;static StudioLiveClient client;static XmlDocument received;static List<string> results=new List<string>();
 static object F(string n){return typeof(StudioForm).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);}static void Call(string n,params object[] a){typeof(StudioForm).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic,null,a.Select(v=>v.GetType()).ToArray(),null).Invoke(form,a);}static void Wait(Func<bool> c){var t=Stopwatch.StartNew();while(!c()&&t.ElapsedMilliseconds<15000){Application.DoEvents();Thread.Sleep(20);}if(!c())throw new Exception("Timeout: "+((Label)F("liveNotice")).Text);}static void Check(bool c,string n){if(!c)throw new Exception(n);results.Add("PASS "+n);Console.WriteLine("PASS "+n);}static XmlDocument Snapshot(){received=null;client.Send(LiveWire.Document("snapshot"));Wait(()=>received!=null);var d=received;Wait(()=>(bool)F("liveVerified"));return d;}static string V(XmlDocument d,int id,string key){return d.SelectSingleNode("/live/control[@id='"+id+"']/value[@key='"+key+"']").InnerText;}
 [STAThread]static int Main(string[] args){try{Directory.CreateDirectory(args[2]);Environment.SetEnvironmentVariable("MP1_SKIN_STUDIO_LIVE_DIR",args[1]);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);form=new StudioForm(args[0]);form.Show();form.PrepareExternalPreview(args[0],"studio.live.special.xml","");Call("ConnectLive");Wait(()=>(bool)F("liveVerified"));client=(StudioLiveClient)F("liveClient");client.Response+=d=>{if(d.DocumentElement.GetAttribute("command")=="snapshot")received=d;};Console.WriteLine("Connected to fixture.");var baseline=Snapshot();var p=(SkinProject)F("project");var target=p.Controls.First(c=>c.Get("id")=="21203");string source=File.ReadAllText(target.Source.Path),refs=File.ReadAllText(p.Resolve("references.xml"));Call("SelectControl",target);
 int revision=(int)F("liveRevision");bool shown=false;revision=(int)F("liveRevision");using(var timer=new System.Windows.Forms.Timer{Interval=40}){timer.Tick+=(s,e)=>{var d=Application.OpenForms.OfType<EffectsDialog>().FirstOrDefault();if(d==null)return;timer.Stop();shown=true;d.Controls.OfType<Button>().Single(b=>b.Text=="Add effect").PerformClick();d.DrawToBitmap(new System.Drawing.Bitmap(d.Width,d.Height),d.ClientRectangle);d.Controls.OfType<Button>().Single(b=>b.Text=="Apply effects").PerformClick();};timer.Start();Call("EditElementEffects");timer.Stop();}Wait(()=>(bool)F("liveVerified")&&(int)F("liveAcknowledged")>revision);Check(V(Snapshot(),21203,"animations")=="2 native effects","Structured effects reach the native control");Check(shown&&p.Undo.Count==1,"Effects dialog applies structured effects and previews them in full MP");revision=(int)F("liveRevision");Call("UndoEditor",false);Wait(()=>(int)F("liveAcknowledged")>revision);Check(V(Snapshot(),21203,"animations")==V(baseline,21203,"animations"),"Native effect state follows Undo");Check(true,"Effect Undo restores native effect count without page reload");target=p.Controls.First(c=>c.Get("id")=="21205");Call("SelectControl",target);shown=false;revision=(int)F("liveRevision");using(var timer=new System.Windows.Forms.Timer{Interval=40}){timer.Tick+=(s,e)=>{var d=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text.StartsWith("Shared default"));if(d==null)return;timer.Stop();shown=true;var choice=d.Controls.OfType<ChoiceBox>().Single(c=>c.AccessibleName=="Shared default font");choice.SelectedIndex=choice.Items.FindIndex(o=>o.ToString()=="font18");d.Controls.OfType<Button>().Single(b=>b.Text=="Apply shared default").PerformClick();};timer.Start();Call("EditReferenceDefault");timer.Stop();}Wait(()=>(int)F("liveAcknowledged")>revision);Check(V(Snapshot(),21205,"font")=="font18","Inherited shared font reaches native control");Check(shown&&p.Dirty,"Shared font dialog previews an inherited loaded alias in full MP");Check(p.Controls.First(c=>c.Get("id")=="21203").Get("font")=="font18","Shared default preserves explicit local font override");revision=(int)F("liveRevision");Call("UndoEditor",false);Wait(()=>(int)F("liveAcknowledged")>revision);Check(V(Snapshot(),21205,"font")==V(baseline,21205,"font"),"Native shared font follows Undo");Check(true,"Shared default Undo restores native font alias");Check(File.ReadAllText(target.Source.Path)==source&&File.ReadAllText(p.Resolve("references.xml"))==refs,"Effects and shared defaults leave original disk XML unchanged");Call("DisconnectLive");Wait(()=>F("liveClient")==null);Check(!p.Dirty,"Disconnect retains clean editor after both Undos");Console.WriteLine(results.Count+" real Studio special workflow checks passed.");return 0;}catch(Exception ex){results.Add(ex.ToString());Console.Error.WriteLine(ex);return 1;}finally{if(form!=null)form.Dispose();Directory.CreateDirectory(args[2]);File.WriteAllLines(Path.Combine(args[2],"Results.txt"),results);}}
}
